<body>
  <main id="app"></main>
  <script type="module">
    const app = document.querySelector('#app');
    const escapeHtml = (value) => String(value).replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character]);

    async function getProject(id) {
      const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
      return response.ok ? response.json() : null;
    }

    async function renderList() {
      app.innerHTML = `
        <h1>Workboard</h1>
        <form id="create-project">
          <label for="project-name">Project name</label>
          <input id="project-name" name="name" type="text" aria-label="Project name">
          <button type="submit">Create project</button>
        </form>
        <p id="message" role="alert" hidden></p>
        <label for="project-filter">Project filter</label>
        <select id="project-filter"><option>Active</option><option>Archived</option></select>
        <section id="projects" aria-label="Projects"></section>`;
      const form = app.querySelector('#create-project');
      const input = app.querySelector('#project-name');
      const message = app.querySelector('#message');
      const list = app.querySelector('#projects');
      const filter = app.querySelector('#project-filter');

      async function refresh() {
        const response = await fetch(`/api/projects?filter=${filter.value}`);
        const projects = await response.json();
        list.innerHTML = projects.map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeHtml(project.name)}</span>
            <span data-testid="project-summary">${project.completedCount}/${project.totalCount} completed</span>
            <button type="button" data-project-id="${project.id}">Open project</button>
            <button type="button" data-archive-id="${project.id}">${filter.value === 'Active' ? 'Archive project' : 'Restore project'}</button>
          </div>`).join('');
        list.querySelectorAll('button[data-project-id]').forEach((button) => {
          button.addEventListener('click', () => { window.location.href = `/projects/${button.dataset.projectId}`; });
        });
        list.querySelectorAll('button[data-archive-id]').forEach((button) => {
          button.addEventListener('click', async () => {
            const action = filter.value === 'Active' ? 'archive' : 'restore';
            await fetch(`/api/projects/${button.dataset.archiveId}/${action}`, { method: 'POST' });
            await refresh();
          });
        });
      }

      filter.addEventListener('change', refresh);
      form.addEventListener('submit', async (event) => {
        event.preventDefault();
        message.hidden = true;
        const response = await fetch('/api/projects', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ name: input.value.trim() }),
        });
        if (!response.ok) {
          message.textContent = 'Project name is required';
          message.hidden = false;
          return;
        }
        input.value = '';
        await refresh();
      });
      await refresh();
    }

    async function renderProject(id) {
      const project = await getProject(id);
      if (!project) {
        app.innerHTML = '<h1>Project not found</h1><button type="button" id="back">Projects</button>';
      } else {
        app.innerHTML = `
          <h1>${escapeHtml(project.name)}</h1>
          <button type="button" id="back">Projects</button>
          ${project.archived ? '<p>Archived project</p>' : ''}
          <form id="rename-project">
            <label for="new-project-name">New project name</label>
            <input id="new-project-name" name="name" type="text" aria-label="New project name" ${project.archived ? 'disabled' : ''}>
            <button type="submit" ${project.archived ? 'disabled' : ''}>Rename project</button>
          </form>
          <form id="create-task">
            <label for="task-title">Task title</label>
            <input id="task-title" name="title" type="text" aria-label="Task title" ${project.archived ? 'disabled' : ''}>
            <button type="submit" ${project.archived ? 'disabled' : ''}>Create task</button>
          </form>
          <p id="message" role="alert" hidden></p>
          <label for="task-filter">Task filter</label>
          <select id="task-filter">
            <option>All</option><option>Open</option><option>Completed</option>
          </select>
          <section id="tasks" aria-label="Tasks"></section>`;
        const form = app.querySelector('#create-task');
        const renameForm = app.querySelector('#rename-project');
        const renameInput = app.querySelector('#new-project-name');
        const input = app.querySelector('#task-title');
        const message = app.querySelector('#message');
        const filter = app.querySelector('#task-filter');
        const list = app.querySelector('#tasks');

        async function refresh() {
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`);
          const tasks = await response.json();
          const visible = tasks.filter((task) => filter.value === 'All'
            || (filter.value === 'Open' && !task.completed)
            || (filter.value === 'Completed' && task.completed));
          list.innerHTML = visible.map((task) => `
            <div class="task-row" data-testid="task-row">
              <input type="checkbox" id="task-${task.id}" data-task-id="${task.id}" ${task.completed ? 'checked' : ''} ${project.archived ? 'disabled' : ''} aria-label="Complete ${escapeHtml(task.title)}">
              <label for="task-${task.id}">${escapeHtml(task.title)}</label>
            </div>`).join('');
          list.querySelectorAll('input[data-task-id]').forEach((checkbox) => {
            checkbox.addEventListener('change', async () => {
              await fetch(`/api/projects/${encodeURIComponent(id)}/tasks/${checkbox.dataset.taskId}`, {
                method: 'PATCH',
                headers: { 'content-type': 'application/json' },
                body: JSON.stringify({ completed: checkbox.checked }),
              });
              await refresh();
            });
          });
        }

        filter.addEventListener('change', refresh);
        renameForm.addEventListener('submit', async (event) => {
          event.preventDefault();
          message.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}`, {
            method: 'PATCH',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ name: renameInput.value.trim() }),
          });
          if (!response.ok) {
            message.textContent = 'Project name is required';
            message.hidden = false;
            return;
          }
          const updatedProject = await response.json();
          app.querySelector('h1').textContent = updatedProject.name;
          renameInput.value = '';
        });
        form.addEventListener('submit', async (event) => {
          event.preventDefault();
          message.hidden = true;
          const response = await fetch(`/api/projects/${encodeURIComponent(id)}/tasks`, {
            method: 'POST',
            headers: { 'content-type': 'application/json' },
            body: JSON.stringify({ title: input.value.trim() }),
          });
          if (!response.ok) {
            message.textContent = 'Task title is required';
            message.hidden = false;
            return;
          }
          input.value = '';
          await refresh();
        });
        await refresh();
      }
      app.querySelector('#back').addEventListener('click', () => { window.location.href = '/'; });
    }

    const match = window.location.pathname.match(/^\/projects\/(\d+)$/);
    if (match) await renderProject(match[1]);
    else await renderList();
  </script>
</body>
